import { cn } from '@/lib/utils.ts'

/**
 * One continuous signal line for the wordmark: clean as it crosses THROUGH,
 * then ramping into noise across NOISE. Coordinates are in the full wordmark
 * SVG viewBox, so the strike is independent of live text layout.
 */
function buildWordmarkSignal(): string {
  const startX = 496
  const width = 936
  const mid = 42
  const straightEnd = 548
  let d = `M ${startX} ${mid} L ${startX + straightEnd} ${mid}`
  const segments = 30
  const span = width - straightEnd
  let seed = 9973
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff
    return seed / 0x7fffffff
  }
  for (let i = 1; i <= segments; i += 1) {
    const x = startX + straightEnd + (i / segments) * span
    const ramp = i < segments * 0.3 ? i / (segments * 0.3) : 1
    const y = mid + (rand() - 0.5) * 2 * 28 * ramp
    d += ` L ${x.toFixed(1)} ${y.toFixed(1)}`
  }
  return d
}

